package kvhttp

import java.nio.charset.StandardCharsets

class Request(
    val method: String,
    val target: String,
    val headers: List<Pair<String, String>>,
    val body: ByteArray = ByteArray(0),
) {
    /** Case-insensitive header lookup; returns the first match. */
    fun header(name: String): String? =
        headers.firstOrNull { (key, _) -> key.equals(name, ignoreCase = true) }?.second

    fun withBody(body: ByteArray) = Request(method, target, headers, body)
}

class Response(
    val status: Int,
    val headers: List<Pair<String, String>> = emptyList(),
    val body: ByteArray = ByteArray(0),
) {
    /**
     * Serializes status line and headers, including Content-Length and
     * Connection: close. The body is not included.
     */
    fun serializeHead(): ByteArray = buildString {
        append("HTTP/1.1 ").append(status).append(' ').append(reasonPhrase(status)).append(CRLF)
        for ((key, value) in headers) append(key).append(": ").append(value).append(CRLF)
        // 204 responses must not carry a body; Content-Length is omitted there.
        if (status != 204) append("Content-Length: ").append(body.size).append(CRLF)
        append("Connection: close").append(CRLF).append(CRLF)
    }.toByteArray(StandardCharsets.ISO_8859_1)

    companion object {
        fun empty(status: Int) = Response(status)

        fun text(status: Int, body: String) = Response(
            status,
            listOf("Content-Type" to "text/plain; charset=utf-8"),
            body.toByteArray(StandardCharsets.UTF_8),
        )
    }
}

private const val CRLF = "\r\n"
private const val TOKEN_EXTRA = "!#$%&'*+-.^_`|~"

fun reasonPhrase(status: Int): String = when (status) {
    200 -> "OK"
    201 -> "Created"
    204 -> "No Content"
    400 -> "Bad Request"
    404 -> "Not Found"
    405 -> "Method Not Allowed"
    408 -> "Request Timeout"
    411 -> "Length Required"
    413 -> "Content Too Large"
    431 -> "Request Header Fields Too Large"
    500 -> "Internal Server Error"
    501 -> "Not Implemented"
    505 -> "HTTP Version Not Supported"
    else -> "Unknown"
}

private fun Char.isAsciiAlphanumeric() = this in 'a'..'z' || this in 'A'..'Z' || this in '0'..'9'

private fun Char.isTokenChar() = isAsciiAlphanumeric() || this in TOKEN_EXTRA

private fun String.isToken() = isNotEmpty() && all { it.isTokenChar() }

private fun String.trimSpaceTab() = trim { it == ' ' || it == '\t' }

/**
 * Parses a request head (request line + header fields), given without the
 * terminating blank line and decoded as ISO-8859-1. Returns null if malformed.
 */
fun parseHead(head: String): Request? {
    val lines = head.split(CRLF)
    val requestLine = lines.first()

    // Request line: METHOD SP request-target SP HTTP-version
    val sp1 = requestLine.indexOf(' ')
    if (sp1 < 0) return null
    val sp2 = requestLine.indexOf(' ', sp1 + 1)
    if (sp2 < 0) return null
    val method = requestLine.substring(0, sp1)
    val target = requestLine.substring(sp1 + 1, sp2)
    val version = requestLine.substring(sp2 + 1)
    if (!method.isToken() || target.isEmpty() || !version.startsWith("HTTP/1.")) return null

    val headers = ArrayList<Pair<String, String>>(lines.size - 1)
    for (line in lines.subList(1, lines.size)) {
        val colon = line.indexOf(':')
        if (colon < 0) return null
        val name = line.substring(0, colon)
        if (!name.isToken()) return null
        headers += name to line.substring(colon + 1).trimSpaceTab()
    }
    return Request(method, target, headers)
}

package kvhttp

import java.util.TreeMap
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

/**
 * Thread-safe in-memory key-value store. Keys are kept ordered so that
 * listing them sorted is a linear walk.
 */
class KvStore {
    enum class PutResult { CREATED, REPLACED }

    private val lock = ReentrantReadWriteLock()
    private val data = TreeMap<String, ByteArray>()

    fun put(key: String, value: ByteArray): PutResult = lock.write {
        if (data.put(key, value) == null) PutResult.CREATED else PutResult.REPLACED
    }

    operator fun get(key: String): ByteArray? = lock.read { data[key] }

    fun remove(key: String): Boolean = lock.write { data.remove(key) != null }

    fun keys(): List<String> = lock.read { data.keys.toList() }
}

package kvhttp

import kotlin.system.exitProcess

fun main(args: Array<String>) {
    if (args.size != 1) {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    val port = args[0].takeIf { arg -> arg.isNotEmpty() && arg.all { it in '0'..'9' } }
        ?.toIntOrNull()
        ?.takeIf { it in 1..65535 }
    if (port == null) {
        System.err.println("invalid port: ${args[0]}")
        exitProcess(2)
    }

    try {
        val server = Server(ServerOptions(port = port), Router(KvStore()))
        server.listen()
        server.run()
    } catch (e: Exception) {
        System.err.println("fatal: ${e.message}")
        exitProcess(1)
    }
}

package kvhttp

private const val KV_PREFIX = "/kv/"
private const val MAX_KEY_LENGTH = 64

/** Returns true if [key] matches `[A-Za-z0-9_-]{1,64}`. */
fun isValidKey(key: String): Boolean =
    key.length in 1..MAX_KEY_LENGTH &&
        key.all { it in 'A'..'Z' || it in 'a'..'z' || it in '0'..'9' || it == '_' || it == '-' }

/** Dispatches requests against the key-value API. */
class Router(private val store: KvStore) : (Request) -> Response {
    override fun invoke(request: Request): Response {
        val path = request.target
        return when {
            path == "/health" -> handleHealth(request)
            path == "/kv" -> handleList(request)
            path.startsWith(KV_PREFIX) -> handleKey(request, path.substring(KV_PREFIX.length))
            else -> Response.text(404, "not found")
        }
    }

    private fun handleHealth(request: Request): Response =
        if (request.method != "GET") methodNotAllowed("GET") else Response.text(200, "ok")

    private fun handleList(request: Request): Response {
        if (request.method != "GET") return methodNotAllowed("GET")
        // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is required.
        val body = store.keys().joinToString(",", "[", "]") { "\"$it\"" }
        return Response(200, listOf("Content-Type" to "application/json"), body.toByteArray(Charsets.US_ASCII))
    }

    private fun handleKey(request: Request, key: String): Response {
        if (!isValidKey(key)) return Response.text(400, "invalid key")
        return when (request.method) {
            "GET" -> store[key]
                ?.let { Response(200, listOf("Content-Type" to "application/octet-stream"), it) }
                ?: Response.text(404, "not found")
            "PUT" -> when (store.put(key, request.body)) {
                KvStore.PutResult.CREATED -> Response.empty(201)
                KvStore.PutResult.REPLACED -> Response.empty(200)
            }
            "DELETE" -> if (store.remove(key)) Response.empty(204) else Response.text(404, "not found")
            else -> methodNotAllowed("GET, PUT, DELETE")
        }
    }

    private fun methodNotAllowed(allow: String): Response {
        val base = Response.text(405, "Method Not Allowed")
        return Response(base.status, base.headers + ("Allow" to allow), base.body)
    }
}

package kvhttp

import java.io.IOException
import java.io.InputStream
import java.io.OutputStream
import java.net.InetAddress
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.SocketTimeoutException
import java.nio.charset.StandardCharsets
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import kotlin.time.Duration
import kotlin.time.Duration.Companion.seconds

data class ServerOptions(
    val port: Int = 8080,
    val maxHeadBytes: Int = 64 * 1024,
    val maxBodyBytes: Int = 1024 * 1024,
    val ioTimeout: Duration = 10.seconds,
)

typealias Handler = (Request) -> Response

/**
 * Minimal HTTP/1.1 server: one request per connection, one virtual thread per
 * connection. Listens on 127.0.0.1.
 */
class Server(private val options: ServerOptions, private val handler: Handler) : AutoCloseable {
    private var serverSocket: ServerSocket? = null
    private val executor: ExecutorService = Executors.newVirtualThreadPerTaskExecutor()

    /** Binds and listens; throws [IOException] on failure. */
    fun listen() {
        serverSocket = ServerSocket().apply {
            reuseAddress = true
            bind(InetSocketAddress(InetAddress.getLoopbackAddress(), options.port), BACKLOG)
        }
    }

    /** Accept loop; does not return under normal operation. */
    fun run(): Nothing {
        val listener = checkNotNull(serverSocket) { "listen() must be called before run()" }
        while (true) {
            val socket = try {
                listener.accept()
            } catch (e: IOException) {
                System.err.println("accept: ${e.message}")
                Thread.sleep(10)
                continue
            }
            executor.execute { handleConnection(socket) }
        }
    }

    override fun close() {
        serverSocket?.close()
        executor.shutdownNow()
    }

    private fun handleConnection(socket: Socket): Unit = socket.use {
        try {
            socket.soTimeout = options.ioTimeout.inWholeMilliseconds.toInt()
            socket.tcpNoDelay = true
            val conn = Connection(socket, options)

            val request = try {
                conn.readRequest()
            } catch (e: HttpError) {
                conn.sendResponse(Response.text(e.status, reasonPhrase(e.status)), includeBody = true)
                conn.lingerClose()
                return
            }

            val response = try {
                handler(request)
            } catch (e: Exception) {
                System.err.println("handler error: $e")
                Response.text(500, "Internal Server Error")
            }
            conn.sendResponse(response, includeBody = request.method != "HEAD")
            conn.lingerClose()
        } catch (_: ConnectionClosed) {
            // Peer went away; nothing more to do.
        } catch (_: IOException) {
            // Peer went away; nothing more to do.
        }
    }

    private companion object {
        const val BACKLOG = 1024
    }
}

/** Thrown when the peer misbehaves in a way that should produce an HTTP error. */
private class HttpError(val status: Int) : Exception(null, null, false, false)

/** Thrown when the connection is unusable (peer closed, timeout, I/O error). */
private class ConnectionClosed : Exception(null, null, false, false)

/** Growable byte buffer that is consumed from the front. */
private class InputBuffer {
    private var data = ByteArray(16 * 1024)
    private var start = 0
    private var end = 0

    val size get() = end - start

    fun indexOf(pattern: ByteArray, from: Int = 0): Int {
        val last = end - pattern.size
        var i = start + from
        outer@ while (i <= last) {
            for (j in pattern.indices) {
                if (data[i + j] != pattern[j]) {
                    i++
                    continue@outer
                }
            }
            return i - start
        }
        return -1
    }

    fun readFrom(input: InputStream): Int {
        if (end == data.size) {
            if (start > 0) {
                data.copyInto(data, 0, start, end)
                end -= start
                start = 0
            }
            if (end == data.size) data = data.copyOf(data.size * 2)
        }
        val n = input.read(data, end, data.size - end)
        if (n > 0) end += n
        return n
    }

    fun take(n: Int): ByteArray {
        require(n <= size)
        val out = data.copyOfRange(start, start + n)
        start += n
        return out
    }

    fun takeString(n: Int): String = String(take(n), StandardCharsets.ISO_8859_1)

    fun skip(n: Int) {
        require(n <= size)
        start += n
    }
}

private val CRLF_BYTES = "\r\n".toByteArray(StandardCharsets.ISO_8859_1)
private val HEAD_END_BYTES = "\r\n\r\n".toByteArray(StandardCharsets.ISO_8859_1)

private class Connection(private val socket: Socket, private val options: ServerOptions) {
    private val input: InputStream = socket.getInputStream()
    private val output: OutputStream = socket.getOutputStream()
    private val buffer = InputBuffer()

    fun readRequest(): Request {
        var headEnd: Int
        while (buffer.indexOf(HEAD_END_BYTES).also { headEnd = it } < 0) {
            if (buffer.size > options.maxHeadBytes) throw HttpError(431)
            if (!fill()) throw ConnectionClosed()
        }
        val head = parseHead(buffer.takeString(headEnd)) ?: throw HttpError(400)
        buffer.skip(HEAD_END_BYTES.size)
        return head.withBody(readBody(head))
    }

    fun sendResponse(response: Response, includeBody: Boolean) {
        output.write(response.serializeHead())
        if (includeBody) output.write(response.body)
        output.flush()
    }

    /**
     * Half-closes the socket and discards any remaining input so the client
     * sees the response rather than a reset.
     */
    fun lingerClose() {
        try {
            socket.shutdownOutput()
            socket.soTimeout = 1000
            val scratch = ByteArray(16 * 1024)
            var drained = 0L
            while (drained < MAX_DRAIN) {
                val n = input.read(scratch)
                if (n <= 0) break
                drained += n
            }
        } catch (_: IOException) {
            // Best effort only.
        }
    }

    /** Reads more bytes into the buffer; returns false on EOF. */
    private fun fill(): Boolean = try {
        buffer.readFrom(input) > 0
    } catch (_: SocketTimeoutException) {
        throw HttpError(408)
    } catch (_: IOException) {
        throw ConnectionClosed()
    }

    /** Ensures at least [n] bytes are buffered. */
    private fun require(n: Int) {
        while (buffer.size < n) {
            if (!fill()) throw HttpError(400)
        }
    }

    private fun take(n: Int): ByteArray {
        require(n)
        return buffer.take(n)
    }

    private fun readLine(): String {
        var pos: Int
        while (buffer.indexOf(CRLF_BYTES).also { pos = it } < 0) {
            if (buffer.size > options.maxHeadBytes) throw HttpError(400)
            if (!fill()) throw HttpError(400)
        }
        val line = buffer.takeString(pos)
        buffer.skip(CRLF_BYTES.size)
        return line
    }

    private fun readBody(request: Request): ByteArray {
        request.header("Transfer-Encoding")?.let { te ->
            if (!te.equals("chunked", ignoreCase = true)) throw HttpError(501)
            return readChunkedBody()
        }
        val lengthHeader = request.header("Content-Length") ?: return ByteArray(0)
        if (lengthHeader.isEmpty() || !lengthHeader.all { it in '0'..'9' }) throw HttpError(400)
        val length = lengthHeader.toLongOrNull() ?: throw HttpError(413)
        if (length > options.maxBodyBytes) throw HttpError(413)
        return take(length.toInt())
    }

    private fun readChunkedBody(): ByteArray {
        val body = java.io.ByteArrayOutputStream()
        while (true) {
            val sizeText = readLine().substringBefore(';')
            if (sizeText.isEmpty() || !sizeText.all { it.isHexDigit() }) throw HttpError(400)
            val size = sizeText.toLongOrNull(16) ?: throw HttpError(413)
            if (size == 0L) {
                // Discard trailer fields up to the terminating blank line.
                while (readLine().isNotEmpty()) continue
                return body.toByteArray()
            }
            if (size > options.maxBodyBytes - body.size()) throw HttpError(413)
            body.write(take(size.toInt()))
            if (readLine().isNotEmpty()) throw HttpError(400)
        }
    }

    private fun Char.isHexDigit() = this in '0'..'9' || this in 'a'..'f' || this in 'A'..'F'

    private companion object {
        const val MAX_DRAIN = 16L * 1024 * 1024
    }
}
